    /**
     * Id
     */
    id?: string | null;
    /**
     * Export Type
     */
    export_type: string;
    /**
     * Status
     */
    status?: string;
    /**
     * Error Message
     */
    error_message?: string | null;
    /**
     * Completed At
     */
    completed_at?: string | null;
